type CaptureRevealElementProps = Omit<
  ComponentProps<typeof CaptureRevealScene>,
  | "from"
  | "durationInFrames"
  | "trimBefore"
  | "playbackRate"
  | "loop"
  | "freeze"
  | "hidden"
  | "name"
  | "showInTimeline"
  | "cropLeft"
  | "cropRight"
  | "cropTop"
  | "cropBottom"
  | "premountFor"
  | "postmountFor"
  | "styleWhilePremounted"
  | "styleWhilePostmounted"
  | "controls"
> & {
  readonly style?: CSSProperties;
};

/** What a prop falls back to when Studio does not pass it, reset included. */
const CaptureRevealDefaults = {
  headline: "no more | keyframes",
  capturing: "Capturing selection...",
  copied: "Copied to clipboard.",
  src: staticFile("capture-reveal/photo-1.webp"),
  mode: "light",
} satisfies Partial<CaptureRevealElementProps>;

/** The Inspector's controls. Timing, transform, crop and premount come with `wrapInSequence`. */
const CaptureRevealSchema = {
  headline: {
    type: "text-content",
    default: "no more | keyframes",
    description: "Headline (| breaks a line)",
  },
  capturing: {
    type: "text-content",
    default: "Capturing selection...",
    description: "Toast while capturing",
  },
  copied: {
    type: "text-content",
    default: "Copied to clipboard.",
    description: "Toast when done",
  },
  src: {
    type: "asset",
    assetType: "image",
    default: staticFile("capture-reveal/photo-1.webp"),
    description: "Screenshot",
  },
  mode: {
    type: "enum",
    default: "light",
    description: "Theme",
    variants: { light: {}, dark: {} },
  },
  fontFamily: { type: "font-family", default: undefined, description: "Font" },
} as const satisfies InteractivitySchema;

/**
 * In over the first frames, out over the last. Opacity only: nothing moves, so
 * no glyph can snap to the pixel grid on the way out.
 */
function CaptureRevealFade({ children }: { children: ReactNode }) {
  const frame = useCurrentFrame();
  const enter = Math.min(1, (frame + 1) / 6);
  const { durationInFrames } = useVideoConfig();
  const left = Math.min(1, Math.max(0, (durationInFrames - 1 - frame) / 12));
  const leave = left * left;
  return (
    <AbsoluteFill showInTimeline={false} style={{ opacity: enter * leave }}>
      {children}
    </AbsoluteFill>
  );
}

const CaptureRevealInner = forwardRef<
  HTMLDivElement,
  CaptureRevealElementProps
>(({ style, ...props }, ref) => {
  // The layer's length, from the Sequence `wrapInSequence` puts around this.
  const { durationInFrames } = useVideoConfig();
  const rest = { ...CaptureRevealDefaults, ...props };
  // The scene measures its copy once, on mount. An Inspector edit changes the
  // props without remounting it, so the key does.
  const key = JSON.stringify(props, (k, v) =>
    k === "children" ? undefined : v,
  );

  // width/height are what useVideoConfig() reports inside this Sequence, so
  // the scene lays itself out in its stage rather than the whole composition.
  // It is not a layer of its own: the one Studio shows is the wrapper's.
  return (
    <Sequence
      layout="none"
      showInTimeline={false}
      durationInFrames={durationInFrames}
      width={1280}
      height={720}
    >
      <div
        ref={ref}
        style={{
          position: "relative",
          width: 1280,
          height: 720,
          overflow: "hidden",
          color: "black",
          fontFamily: "initial",
          fontSize: 16,
          fontStyle: "normal",
          fontVariant: "normal",
          fontWeight: 400,
          fontStretch: "normal",
          fontKerning: "auto",
          fontFeatureSettings: "normal",
          fontVariationSettings: "normal",
          lineHeight: "normal",
          letterSpacing: "normal",
          wordSpacing: "normal",
          textAlign: "start",
          textIndent: 0,
          textTransform: "none",
          textShadow: "none",
          textRendering: "auto",
          whiteSpace: "normal",
          wordBreak: "normal",
          overflowWrap: "normal",
          hyphens: "manual",
          direction: "ltr",
          visibility: "visible",
          ...style,
        }}
      >
        <CaptureRevealFade>
          <CaptureRevealScene key={key} {...rest} />
        </CaptureRevealFade>
      </div>
    </Sequence>
  );
});

export const CaptureReveal = Interactive.withSchema({
  Component: CaptureRevealInner,
  componentName: "<CaptureReveal>",
  schema: CaptureRevealSchema,
  wrapInSequence: true,
});
